local ADDON_NAME, ns = ...
local L = ns.L or setmetatable({}, { __index = function(_, k) return k end })

---------------------------------------------------------------------------
-- Starter data (beta nodes)
--   Data\StarterData.lua is generated by tools/export_starter.py from
--   collected SavedVariables. Each new data version is imported once.
--   Imported nodes are marked source = "starter". They become normal nodes
--   once we harvest them. Nodes nobody confirms expire after EXPIRE_DAYS,
--   so wrong beta positions clean themselves up after launch.
---------------------------------------------------------------------------
local EXPIRE_DAYS = 21
local MERGE_RADIUS = 10 -- yards, same as the recorder
local EMPTY_MEMORY = 3 * 3600 -- seconds an "it was empty here" is remembered over logouts
local TYPES = { h = "herb", o = "ore", c = "chest" }

---------------------------------------------------------------------------
-- Known spawn points from Questie (Data\QuestieNodes.lua)
--   Node data from Questie (https://github.com/Questie/Questie), used with
--   permission. Stored compactly and imported zone by zone: a zone is
--   loaded the first time you enter it or look at it on the world map.
--   These are possible spawn points: not every one is up at the same time.
--
--   They live in memory only. Your SavedVariables keep just the list of
--   zones you had loaded and the few spawn points that are resting (empty
--   or just harvested); on logout the rest is dropped and on login loaded
--   again from the addon file. Keeps login, logout and /reload fast.
---------------------------------------------------------------------------
local loaded = {} -- mapID -> true: imported this session

local function SpawnKey(id, x, y)
    return id .. ":" .. x .. ":" .. y -- packed coordinates from the data file
end

-- Name of a known node kind in the client's language: herbs are called
-- like the herb they give; others keep the English name until gathered once
-- shipped name in the chosen language (Data/NodeNames.lua, from Questie)
local function ShippedNodeName(oid)
    local lang = ns.Language and ns.Language() or "enUS"
    if lang:sub(1, 2) == "en" then
        local data = GathercraftQuestieData
        local kind = data and data.kinds[oid]
        return kind and kind[3]
    end
    local names = GathercraftNodeNames and (GathercraftNodeNames[lang] or GathercraftNodeNames[GetLocale()])
    return names and names[tonumber(oid:sub(2))]
end

local function LocalKindName(oid, kind)
    local lang = ns.Language and ns.Language() or "enUS"
    if lang:sub(1, 2) ~= "en" then
        local shipped = ShippedNodeName(oid)
        if shipped then return shipped end
    end
    local known = ns.KnownName(oid)
    if known then return known end
    if lang:sub(1, 2) ~= "en" and kind[1] == "h" and kind[2] > 0 and C_Item and C_Item.GetItemNameByID then
        local name = C_Item.GetItemNameByID(kind[2])
        if name and name ~= "" then return name end
    end
    return kind[3]
end

-- Every stored node with a known object gets its name in the chosen
-- language (own nodes keep the name they were gathered with otherwise)
local function LocalizeNodeNames()
    if not (ns.db and ns.db.nodes) then return end
    local changed = 0
    for _, list in pairs(ns.db.nodes) do
        for _, n in ipairs(list) do
            local name = n.id and n.id:match("^o%d+$") and ShippedNodeName(n.id)
            if name and name ~= n.name then
                n.name = name
                changed = changed + 1
            end
        end
    end
    if changed > 0 and ns.NotifyNodesChanged then ns.NotifyNodesChanged() end
end
ns.LocalizeNodeNames = LocalizeNodeNames
table.insert(ns.languageListeners, LocalizeNodeNames)

local function ImportQuestieZone(mapID, quiet)
    local data = GathercraftQuestieData
    if not (data and mapID and ns.db) or loaded[mapID] then return 0 end
    loaded[mapID] = true
    local packed = data.zones[mapID]
    if not packed then return 0 end
    ns.db.spawnZones = ns.db.spawnZones or {}
    local firstTime = not ns.db.spawnZones[mapID]
    ns.db.spawnZones[mapID] = true
    local state = ns.db.spawnState and ns.db.spawnState[mapID]
    local now = time()

    ns.db.nodes[mapID] = ns.db.nodes[mapID] or {}
    local list, added = ns.db.nodes[mapID], 0
    for id, xs, ys in packed:gmatch("(%d+),(%d+),(%d+)") do
        local oid = "o" .. id
        local kind = data.kinds[oid]
        if kind then
            local x, y = tonumber(xs) / 10000, tonumber(ys) / 10000
            if not ns.FindNode(mapID, oid, x, y, MERGE_RADIUS) then
                local key = SpawnKey(oid, xs, ys)
                local n = {
                    id = oid, type = TYPES[kind[1]], name = LocalKindName(oid, kind), x = x, y = y,
                    count = 0, item = kind[2] > 0 and kind[2] or nil,
                    source = "questie", last = 0, sk = key,
                }
                local st = state and state[key]
                if st then
                    -- "until:streak[:hits:misses:emptyAt]" (older saves have only the first two)
                    local untilT, streak, hits, misses, emptyAt = st:match("^(%d+):(%d+):?(%d*):?(%d*):?(%d*)$")
                    untilT, streak = tonumber(untilT), tonumber(streak)
                    hits, misses, emptyAt = tonumber(hits), tonumber(misses), tonumber(emptyAt)
                    if untilT and untilT > now then n.emptyUntil = untilT end
                    if streak and streak > 0 then n.emptyStreak = streak end
                    if hits and hits > 0 then n.hits = hits end
                    if misses and misses > 0 then n.misses = misses end
                    if emptyAt and emptyAt > 0 and now - emptyAt < EMPTY_MEMORY then n.emptyAt = emptyAt end
                end
                table.insert(list, n)
                added = added + 1
            end
        end
    end
    if added > 0 then
        ns.NotifyNodesChanged()
        if not quiet and firstTime then
            ns.Print((L["Loaded %d known spawn points for %s."]):format(added, ns.GetZoneName(mapID)))
        end
    end
    return added
end

-- Logout / reload: keep only what we can't get back from the addon file
local function SaveSpawnState()
    if not ns.db then return end
    local state, now = {}, time()
    for mapID, list in pairs(ns.db.nodes) do
        local keep = {}
        for _, n in ipairs(list) do
            if n.source == "questie" then
                local resting = n.emptyUntil and n.emptyUntil > now
                local emptyAt = n.emptyAt and now - n.emptyAt < EMPTY_MEMORY and n.emptyAt or 0
                if n.sk and (resting or n.emptyStreak or n.hits or n.misses) then
                    state[mapID] = state[mapID] or {}
                    if n.hits or n.misses or emptyAt > 0 then
                        state[mapID][n.sk] = ("%d:%d:%d:%d:%d"):format(resting and n.emptyUntil or 0,
                            n.emptyStreak or 0, n.hits or 0, n.misses or 0, emptyAt)
                    else
                        state[mapID][n.sk] = ("%d:%d"):format(resting and n.emptyUntil or 0, n.emptyStreak or 0)
                    end
                end
            else
                keep[#keep + 1] = n
            end
        end
        ns.db.nodes[mapID] = #keep > 0 and keep or nil
    end
    ns.db.spawnState = state
end

-- Login: load the zones you had loaded before, a few per frame
local function ReloadSpawnZones()
    local zones = {}
    -- older versions remembered loaded zones as questieZones
    for mapID in pairs(ns.db.questieZones or {}) do zones[#zones + 1] = mapID end
    for mapID in pairs(ns.db.spawnZones or {}) do zones[#zones + 1] = mapID end
    ns.db.questieZones = nil
    ns.db.spawnZones = ns.db.spawnZones or {}
    for _, mapID in ipairs(zones) do ns.db.spawnZones[mapID] = true end
    local i = 0
    local function step()
        for _ = 1, 2 do
            i = i + 1
            local mapID = zones[i]
            if not mapID then return end
            ImportQuestieZone(mapID, true)
        end
        C_Timer.After(0.05, step)
    end
    step()
end

-- Is this node one of the known spawn points? Everyone has those already,
-- so sync never needs to send them. Parsed per zone on first use.
local spawnIndex = {}
ns.IsKnownSpawn = function(mapID, id, x, y)
    local data = GathercraftQuestieData
    if not (data and mapID and id) then return false end
    local byId = spawnIndex[mapID]
    if not byId then
        byId = {}
        for sid, sx, sy in (data.zones[mapID] or ""):gmatch("(%d+),(%d+),(%d+)") do
            local key = "o" .. sid
            byId[key] = byId[key] or {}
            table.insert(byId[key], { tonumber(sx) / 10000, tonumber(sy) / 10000 })
        end
        spawnIndex[mapID] = byId
    end
    for _, p in ipairs(byId[id] or {}) do
        if math.abs(p[1] - x) < 0.01 and math.abs(p[2] - y) < 0.01
            and ns.Distance(mapID, x, y, p[1], p[2]) <= MERGE_RADIUS * 1.5 then
            return true
        end
    end
    return false
end

ns.ImportQuestieZone = function(mapID, quiet) return ImportQuestieZone(mapID, quiet) end

-- Do we ship known spawn points for this zone? (no: a new Forever zone)
ns.HasKnownSpawns = function(mapID)
    local data = GathercraftQuestieData
    return data and data.zones and mapID and data.zones[mapID] ~= nil or false
end

-- /gcr loadall : every zone of the current continent at once (for long routes)
ns.LoadQuestieContinent = function()
    local data = GathercraftQuestieData
    local mapID = ns.GetPlayerPos()
    if not (data and mapID) then return end
    local continent = ns.GetContinent(mapID)
    local added, zones = 0, 0
    for zoneMapID in pairs(data.zones) do
        if ns.GetContinent(zoneMapID) == continent then
            local n = ImportQuestieZone(zoneMapID, true)
            if n > 0 then zones = zones + 1 end
            added = added + n
        end
    end
    if added > 0 then
        ns.Print((L["Loaded %d known spawn points in %d more zones of this continent."]):format(added, zones))
    else
        ns.Print(L["All known spawn points of this continent are already loaded."])
    end
end

local function ImportCurrentZone()
    local mapID = ns.GetPlayerPos()
    if mapID then ImportQuestieZone(mapID) end
end

local function Confirmed(n)
    return n.source ~= "starter" or (n.heard or 0) >= 1 or n.seenAt ~= nil
end

-- Removes starter nodes that nobody confirmed in time
local function ExpireOld()
    local limit = time() - EXPIRE_DAYS * 86400
    local removed = 0
    for _, list in pairs(ns.db.nodes) do
        for i = #list, 1, -1 do
            local n = list[i]
            if n.source == "starter" and not Confirmed(n) and (n.added or 0) < limit then
                table.remove(list, i)
                removed = removed + 1
            end
        end
    end
    if removed > 0 then
        ns.Print((L["Removed %d old beta nodes nobody confirmed."]):format(removed))
        ns.NotifyNodesChanged()
    end
end

local function Import(data)
    local now, added, known = time(), 0, 0
    for mapID, list in pairs(data.nodes or {}) do
        ns.db.nodes[mapID] = ns.db.nodes[mapID] or {}
        for _, e in ipairs(list) do
            local id, t, x, y, item, reporters, name = unpack(e)
            x, y = x / 10000, y / 10000
            if ns.FindNode(mapID, id, x, y, MERGE_RADIUS) then
                known = known + 1
            else
                local node = {
                    id = id, type = TYPES[t], name = name or id,
                    x = x, y = y, count = reporters or 1,
                    item = (item and item > 0) and item or nil,
                    source = "starter", added = now, last = now,
                }
                table.insert(ns.db.nodes[mapID], node)
                ns.NotifyNodesChanged("add", mapID, node)
                added = added + 1
            end
        end
    end
    ns.db.starterVersion = data.version
    ns.Print((L["Beta data %s: %d nodes added, %d already known."]):format(
        tostring(data.version), added, known))
end

local loader = CreateFrame("Frame")
loader:RegisterEvent("PLAYER_LOGIN")
loader:RegisterEvent("PLAYER_LOGOUT")
loader:SetScript("OnEvent", function(_, event)
    if event == "PLAYER_LOGOUT" then
        SaveSpawnState()
        return
    end
    ReloadSpawnZones()
    LocalizeNodeNames()
    local data = GathercraftStarterData
    if data and data.version and ns.db.starterVersion ~= data.version then
        Import(data)
    end
    ExpireOld()
    C_Timer.After(2, ImportCurrentZone)
    -- Zones looked at on the world map are loaded too
    if WorldMapFrame and WorldMapFrame.OnMapChanged and hooksecurefunc then
        hooksecurefunc(WorldMapFrame, "OnMapChanged", function(frame)
            local ok, mapID = pcall(frame.GetMapID, frame)
            if ok and mapID then ImportQuestieZone(mapID) end
        end)
    end
end)

local zoneWatch = CreateFrame("Frame")
zoneWatch:RegisterEvent("ZONE_CHANGED_NEW_AREA")
zoneWatch:SetScript("OnEvent", function()
    C_Timer.After(1, ImportCurrentZone)
end)
